update public.ingredients i
set nutrients = p.nutrient_values || coalesce(i.nutrients,'{}'::jsonb),
    source = case when coalesce(i.source,'') like '%' || p.note || '%' then i.source else concat_ws(' ',nullif(i.source,''),p.note) end
from profile p
where lower(i.name)=lower(p.name);

